import{_ as i,C as d,o as t,c,a0 as a,b as s,w as o,a as r,E as l,a1 as u}from"./chunks/framework.DYS8d9tm.js";const _=JSON.parse('{"title":"Bank Statement Ingestion Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"technical/data ingestion/statement_ingestion.md","filePath":"technical/data ingestion/statement_ingestion.md"}'),m={name:"technical/data ingestion/statement_ingestion.md"};function p(g,e,h,f,y,S){const n=d("Mermaid");return t(),c("div",null,[e[1]||(e[1]=a('<h1 id="bank-statement-ingestion-pipeline" tabindex="-1">Bank Statement Ingestion Pipeline <a class="header-anchor" href="#bank-statement-ingestion-pipeline" aria-label="Permalink to &quot;Bank Statement Ingestion Pipeline&quot;">​</a></h1><p>This document outlines the end-to-end flow for automated and manual bank statement ingestion, parsing, and reconciliation.</p><h2 id="system-overview" tabindex="-1">System Overview <a class="header-anchor" href="#system-overview" aria-label="Permalink to &quot;System Overview&quot;">​</a></h2><p>The ingestion pipeline is designed to securely fetch, decrypt, parse, and reconcile financial statements with minimal user intervention. It supports both automated email synchronization and manual uploads.</p><h2 id="mermaid-flow-diagram" tabindex="-1">Mermaid Flow Diagram <a class="header-anchor" href="#mermaid-flow-diagram" aria-label="Permalink to &quot;Mermaid Flow Diagram&quot;">​</a></h2>',5)),(t(),s(u,null,{default:o(()=>[l(n,{id:"mermaid-15",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BStart%20Sync%20%2F%20Upload%5D%20--%3E%20B%7BSource%20Type%3F%7D%0A%20%20%20%20B%20--%20Email%20--%3E%20C%5BScan%20Inbox%20via%20IMAP%5D%0A%20%20%20%20C%20--%3E%20D%5BIdentify%20PDF%20Attachments%5D%0A%20%20%20%20B%20--%20Manual%20--%3E%20E%5BUpload%20File%20to%20API%5D%0A%20%20%20%20D%20--%3E%20F%5BCheck%20PDF%20Encryption%5D%0A%20%20%20%20E%20--%3E%20F%0A%20%20%20%20%0A%20%20%20%20F%20--%20Encrypted%20--%3E%20G%7BDecryption%20Trial%7D%0A%20%20%20%20F%20--%20Not%20Encrypted%20--%3E%20L%5BHeuristic%20Validation%5D%0A%20%20%20%20%0A%20%20%20%20G%20--%20Cached%20Password%20--%3E%20H%5BAttempt%20Unlock%5D%0A%20%20%20%20G%20--%20Profile%20Heuristics%20--%3E%20I%5BTry%20PAN%20%2F%20Name%20%2B%20DOB%5D%0A%20%20%20%20G%20--%20Manual%20Input%20--%3E%20J%5BUser%20Provided%20PWD%5D%0A%20%20%20%20%0A%20%20%20%20H%20--%20Success%20--%3E%20L%0A%20%20%20%20I%20--%20Success%20--%3E%20L%0A%20%20%20%20J%20--%20Success%20--%3E%20L%0A%20%20%20%20H%20--%20Fail%20--%3E%20K%5BMark%20Status%3A%20PENDING%5D%0A%20%20%20%20I%20--%20Fail%20--%3E%20K%0A%20%20%20%20%0A%20%20%20%20L%20--%20Success%20--%3E%20M%5BExternal%20Parser%20Service%5D%0A%20%20%20%20L%20--%20Fail%20--%3E%20N%5BDiscard%20%2F%20Log%20Error%5D%0A%20%20%20%20%0A%20%20%20%20M%20--%3E%20O%5BExtract%20Transactions%20%26%20Account%20Mask%5D%0A%20%20%20%20O%20--%3E%20P%5BSave%20Original%20to%20Vault%5D%0A%20%20%20%20P%20--%3E%20Q%5BMatch%20%2F%20Create%20Account%20Record%5D%0A%20%20%20%20Q%20--%3E%20R%5BPopulate%20StatementTransactions%5D%0A%20%20%20%20R%20--%3E%20S%5BApply%20Rules%20Engine%20Categories%5D%0A%20%20%20%20S%20--%3E%20T%5BRun%20Fuzzy%20Reconciliation%5D%0A%20%20%20%20T%20--%3E%20U%5BFinal%20Status%3A%20PARSED%5D%0A%20%20%20%20%0A%20%20%20%20K%20--%3E%20V%5BUser%20Dashboard%20Alert%5D%0A%20%20%20%20V%20--%3E%20J%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="detailed-component-breakdown" tabindex="-1">Detailed Component Breakdown <a class="header-anchor" href="#detailed-component-breakdown" aria-label="Permalink to &quot;Detailed Component Breakdown&quot;">​</a></h2><h3 id="_1-discovery-fetching" tabindex="-1">1. Discovery &amp; Fetching <a class="header-anchor" href="#_1-discovery-fetching" aria-label="Permalink to &quot;1. Discovery &amp; Fetching&quot;">​</a></h3><ul><li><strong>Email Configuration</strong>: Users provide IMAP credentials. The system stores the <code>last_sync_at</code> timestamp to prevent duplicate scans.</li><li><strong>Pattern Matching</strong>: Subject lines and senders are searched for financial/CAS statements (<code>statement</code>, <code>e-statement</code>, <code>Consolidated Account Statement</code>, <code>camsonline</code>). Only <code>.pdf</code> attachments are considered.</li><li><strong>Pre-Vault Ignore Rules (<code>source=&quot;STATEMENT&quot;</code>)</strong>: Before attempting decryption, saving to Vault, or creating a <code>Statement</code> row, <code>_process_email_message</code> decodes MIME <code>From</code>, <code>Subject</code>, and filename headers and checks PostgreSQL <code>spam_filters</code> rules via <code>IngestionService.check_ignore_rules(..., source=&quot;STATEMENT&quot;)</code>. Matching promotional/margin/TDS PDFs increment <code>count_blocked</code> and are skipped cleanly without polluting Vault or Statements.</li></ul><h3 id="_2-the-decryption-engine-statementpasswordservice" tabindex="-1">2. The Decryption Engine (<code>StatementPasswordService</code>) <a class="header-anchor" href="#_2-the-decryption-engine-statementpasswordservice" aria-label="Permalink to &quot;2. The Decryption Engine (`StatementPasswordService`)&quot;">​</a></h3><p>The decryption system is encapsulated within a modular service (<code>StatementPasswordService</code> in <code>Backend/app/modules/ingestion/password_service.py</code>), utilizing a tiered authentication hierarchy:</p><ol><li><strong>Manual Input (Absolute Priority)</strong>: Explicit user-provided passwords. When an entered password succeeds, it is <strong>immediately cached</strong> into <code>StatementPasswordCache</code> (indexed by <code>account_mask</code>, <code>sender_email</code>, and a tenant-level fallback) so future uploads of the same statement type unlock automatically without repeated prompting.</li><li><strong>Cached Passwords</strong>: Securely stores previously working passwords mapped by <code>account_mask</code> (most specific, per-card) or <code>sender_email</code> (per-bank), falling back to all successful tenant passwords.</li><li><strong>User Profile Candidates</strong>: Standalone candidate generation from profile metadata: <ul><li><strong>PAN</strong>: Standard Indian PAN (both uppercase and lowercase).</li><li><strong>Name+DOB</strong>: <code>[First 4 Alpha of Name] + [DDMM]</code> / <code>DDMMYY</code> / <code>DDMMYYYY</code> across casing variations.</li><li><strong>Mobile+DOB</strong>: <code>[Last 5 digits of Mobile] + [DDMMYY]</code> (e.g. SBI Credit Cards).</li><li><strong>Name+Account Mask</strong>: <code>[First 4 Alpha of Name] + [Last 4 Account Digits]</code>.</li><li><strong>Pure Date Formats</strong>: <code>DDMMYYYY</code>, <code>DDMMYY</code>, <code>DDMM</code>.</li></ul></li><li><strong>Manual Retry &amp; Partial-Unlock Continuity</strong>: If automated trials fail, the statement is saved in a <code>PENDING</code> state. When retried (<code>POST /finance/statements/{id}/reprocess</code>), if decryption succeeds and saves the unlocked PDF into Vault even when downstream parsing fails, the endpoint returns structured <code>partial_success</code> (<code>unlocked: true, parsed: false</code>) so the UI surfaces both the unlocked Vault PDF and the parse diagnostic.</li><li><strong>Idempotency &amp; Retry Loop Suppression</strong>: Periodic automated background IMAP sync (<code>source=&quot;EMAIL&quot;</code>) checks existing records and immediately skips PDFs already marked <code>FAILED</code> (e.g. corrupt or unsupported schema), avoiding endless 3-hour retry storms while preserving full user control over manual <code>/reprocess</code> retries.</li></ol><h3 id="_3-parsing-extraction" tabindex="-1">3. Parsing &amp; Extraction <a class="header-anchor" href="#_3-parsing-extraction" aria-label="Permalink to &quot;3. Parsing &amp; Extraction&quot;">​</a></h3><ul><li><strong>Heuristics</strong>: Uses <code>pdfplumber</code> to verify keywords (<code>balance</code>, <code>credit</code>, <code>debit</code>, <code>folio</code>, <code>isin</code>) for automated email attachments.</li><li><strong>Normalization</strong>: Pluggable handlers (<code>MutualFundCasHandler</code>, <code>BankStatementHandler</code>) and <code>ExternalParserService</code> normalize bank/card/eCAS layouts into read-only <code>StatementTransaction</code> records across supported banks (HDFC, ICICI, Slice, Bank of Baroda). Specialized handler errors are caught and persisted cleanly as <code>FAILED</code>.</li><li><strong>Modern Engine Upgrades</strong>: Mutual Fund CAS and AMC SOA statements are parsed using <code>casparser 1.x</code> (<code>pypdfium2</code> engine) and PyMuPDF, providing native CAMS, KFintech, CDSL, and NSDL support without legacy 0.8.x monkey-patching.</li></ul><h3 id="_4-storage-vaulting-self-healing" tabindex="-1">4. Storage, Vaulting &amp; Self-Healing <a class="header-anchor" href="#_4-storage-vaulting-self-healing" aria-label="Permalink to &quot;4. Storage, Vaulting &amp; Self-Healing&quot;">​</a></h3><ul><li><strong>Persistent Storage (<code>VAULT_STORAGE_PATH</code>)</strong>: Statements are persisted under <code>/data/vault/&lt;tenant_id&gt;/statements/&lt;doc_id&gt;/vN</code> in Docker (or <code>&lt;workspace&gt;/data/vault</code> locally) once unlocked (or as encrypted <code>v1</code> while <code>PENDING</code>). Extracted <code>StatementTransaction</code> rows are immutable/read-only.</li><li><strong>SHA-256 Deduplication</strong>: <code>_ensure_vault_document</code> compares incoming PDF SHA-256 digests against the active Vault file before uploading, preventing <code>v2..vN</code> duplicate version proliferation on repeated retries or email re-scans.</li><li><strong>Resilient Resolution &amp; Auto-Unlock</strong>: <code>VaultService.resolve_file_path</code> resolves across legacy/ephemeral roots (<code>/data/vault</code> &lt;-&gt; <code>/app/data/vault</code> &lt;-&gt; <code>data/vault</code>), <code>statements/</code> vs. root layouts, and surviving earlier versions. <code>VaultService.heal_legacy_paths</code> runs automatically on backend startup, <code>VaultService.ensure_unlocked_pdf</code> decrypts legacy encrypted PDFs in-place on access, and <code>VaultService.get_documents</code> lazily backfills thumbnails for unlocked PDFs while skipping encrypted ones.</li><li><strong>Data Model</strong>: <ul><li><code>Statement</code>: Metadata (<code>filename</code>, <code>statement_type</code>, <code>account_id</code>, <code>vault_id</code>, <code>status</code>, <code>is_attended</code>, <code>closed_at</code>, <code>email_sender</code>, <code>failure_reason</code>) supporting full statement-level CRUD.</li><li><code>StatementTransaction</code>: Read-only extracted line items awaiting reconciliation.</li></ul></li></ul><h3 id="_5-categorization-reconciliation-attendance-lifecycle" tabindex="-1">5. Categorization, Reconciliation &amp; Attendance Lifecycle <a class="header-anchor" href="#_5-categorization-reconciliation-attendance-lifecycle" aria-label="Permalink to &quot;5. Categorization, Reconciliation &amp; Attendance Lifecycle&quot;">​</a></h3><ul><li><strong>Categorization</strong>: Uses rule-based category matching (<code>TransactionService.get_suggested_category</code>) and dynamic read-time <code>MerchantAlias</code> resolution.</li><li><strong>Fuzzy Matching</strong>: Transactions are matched against existing ledger entries using ref ID or a ±4-day date window, exact signed amount, and matching account.</li><li><strong>Mutual Fund Portfolio Import</strong>: <code>POST /{id}/reconcile-cas</code> ingests selected mutual fund transactions into <code>MutualFundHolding</code> and <code>MutualFundOrder</code>, recalculating holding balances with exact mathematical precision.</li><li><strong>Attendance &amp; Review Lifecycle</strong>: <ul><li><strong>Hidden by Default</strong>: By default, <code>GET /api/v1/finance/statements</code> is queried with <code>is_attended=false</code>, ensuring attended statements remain hidden on initial load across both Web and Mobile apps.</li><li><strong>Toggle Control (<code>Show Attended</code> ↔ <code>Showing Attended</code>)</strong>: When flipped active, clients omit or pass <code>is_attended=undefined</code>, allowing users to inspect all statements (both attended and unattended).</li><li><strong>Real-Time State Reconcile &amp; Auto-Advance</strong>: Marking a statement attended via <code>PATCH /{id}/attend</code> immediately removes it from local active arrays when the attended filter is disabled. The Web UI auto-advances inspector selection to the next statement, and the Mobile app decrements total statement counters in real time.</li><li>Statements can be explicitly marked as attended via <code>PATCH /{id}/attend</code>, setting <code>is_attended=true</code> and stamping <code>closed_at</code>.</li><li>When attended, operational actions (<code>Edit</code>, <code>Reprocess</code>, <code>Import</code>, <code>Reconcile</code>) and transaction checkboxes are disabled to prevent accidental state mutation.</li><li>Individual transactions are <strong>not</strong> marked as imported by attendance; only genuinely imported/reconciled entries display <code>✓ Imported</code> (CAS) or <code>✓ Matched</code> (Bank). Unreconciled entries on attended statements display neutral <code>Unimported</code> or <code>Unmatched</code> badges.</li><li>If a statement is attended with remaining unreconciled items, an alert banner displays the exact unreconciled count.</li><li>Attended statements can be seamlessly reopened at any time via the <code>Reopen</code> button.</li></ul></li><li><strong>Client-Side Ingestion Hardening</strong>: The Statements interface employs request sequence tracking (<code>statementSelectSeq</code> &amp; <code>attachmentLoadSeq</code>) and immediately clears stale table state upon switching statements, eliminating out-of-order response clobbering and visual flicker.</li></ul><h2 id="api-endpoints-api-v1-finance-statements" tabindex="-1">API Endpoints (<code>/api/v1/finance/statements</code>) <a class="header-anchor" href="#api-endpoints-api-v1-finance-statements" aria-label="Permalink to &quot;API Endpoints (`/api/v1/finance/statements`)&quot;">​</a></h2><ul><li><code>GET /</code>: List statements with pagination, <code>search</code>, <code>status</code> (<code>PARSED | PENDING | FAILED</code>), <code>statement_type</code>, and <code>is_attended</code> filters.</li><li><code>GET /{id}</code>: Fetch a single statement record.</li><li><code>POST /upload</code>: Manual PDF upload with optional password and account override.</li><li><code>POST /sync</code>: Trigger background IMAP statement scan.</li><li><code>PATCH /{id}</code>: Update statement-level metadata (<code>filename</code> synced to linked Vault document, <code>statement_type</code>, <code>account_id</code> with auto-reprocess/reconciliation on <code>FAILED</code> statements).</li><li><code>PATCH /{id}/attend</code>: Mark a statement as attended or reopened, toggling <code>is_attended</code> and setting <code>closed_at</code>.</li><li><code>DELETE /{id}</code>: Soft-delete a statement &amp; its transactions (<code>delete_vault_file=true</code> cleans up unreferenced Vault PDFs; <code>create_ignore_rule=true</code> blocks future emails from that sender).</li><li><code>POST /bulk-delete</code>: Batch delete multiple statements with optional Vault cleanup and sender ignore rule creation.</li><li><code>POST /{id}/ignore</code>: Create a <code>STATEMENT</code> ignore rule (<code>sender | subject | pattern</code>) and optionally clean up other matching <code>PENDING</code>/<code>FAILED</code> statements (preserving <code>PARSED</code> records).</li><li><code>POST /{id}/reprocess</code>: Retry decryption/parsing with an optional manual password (preserves original <code>email_sender</code>).</li><li><code>POST /{id}/reconcile</code> &amp; <code>POST /{id}/reconcile-cas</code>: Run bank ledger matching or Mutual Fund portfolio import.</li><li><code>GET /{id}/transactions</code>: View read-only extracted items.</li></ul>',14))])}const v=i(m,[["render",p]]);export{_ as __pageData,v as default};
